@import url('https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap');

:root {
  --bg: #f5f2ed;
  --bg-deep: #ede5d9;
  --ink: #1a1a1a;
  --muted: #6f675f;
  --line: rgba(26, 26, 26, 0.14);
  --terracotta: #bd6d53;
  --sage: #9aa384;
  --sand: #d8bd91;
  --clay: #c89578;
  --cream: #fbf7ef;
  --serif: 'Playfair Display', Georgia, serif;
  --sans: 'Instrument Sans', Helvetica, sans-serif;
  --gutter: clamp(1.2rem, 4vw, 4.5rem);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(circle at 8% 12%, rgba(216, 189, 145, 0.28), transparent 28rem),
    linear-gradient(135deg, rgba(255,255,255,0.18), transparent 42%),
    var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.55;
  text-rendering: optimizeLegibility;
}
body::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0.32;
  background-image: radial-gradient(rgba(26,26,26,0.08) 0.65px, transparent 0.65px);
  background-size: 6px 6px;
  mix-blend-mode: multiply;
  z-index: 30;
}
a { color: inherit; text-decoration: none; }
p { margin: 0; }
::selection { background: var(--terracotta); color: var(--cream); }

.site-header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  padding: 1.35rem var(--gutter);
  background: rgba(245, 242, 237, 0.83);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid rgba(26,26,26,0.06);
}
.logo {
  font-family: var(--serif);
  font-size: clamp(1.55rem, 2.2vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -0.055em;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: clamp(1.1rem, 2.4vw, 2.5rem);
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 600;
}
.nav-links a { position: relative; }
.nav-links a::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -0.28rem;
  height: 1px;
  background: var(--ink);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 240ms ease;
}
.nav-links a:hover,
.nav-links a[aria-current='page'] { color: var(--ink); }
.nav-links a:hover::after,
.nav-links a[aria-current='page']::after { transform: scaleX(1); }
.menu-toggle {
  display: none;
  width: 2.8rem;
  height: 2.8rem;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}
.menu-toggle span,
.menu-toggle::before,
.menu-toggle::after {
  content: '';
  display: block;
  width: 1.05rem;
  height: 1px;
  margin: 0.25rem auto;
  background: currentColor;
  transition: transform 260ms ease, opacity 180ms ease;
}
.menu-open .menu-toggle span { opacity: 0; }
.menu-open .menu-toggle::before { transform: translateY(5px) rotate(45deg); }
.menu-open .menu-toggle::after { transform: translateY(-5px) rotate(-45deg); }
.mobile-overlay {
  position: fixed;
  inset: 0;
  z-index: 15;
  display: grid;
  align-content: center;
  padding: 7rem var(--gutter) 3rem;
  background: rgba(237, 229, 217, 0.98);
  transform: translateY(-100%);
  transition: transform 430ms cubic-bezier(.76,0,.24,1);
}
.menu-open .mobile-overlay { transform: translateY(0); }
.mobile-overlay nav {
  display: grid;
  gap: 0.55rem;
}
.mobile-overlay a {
  font-family: var(--serif);
  font-size: clamp(3.4rem, 17vw, 7rem);
  line-height: 0.9;
  letter-spacing: -0.075em;
}
.mobile-note {
  max-width: 24rem;
  margin-top: 2.3rem;
  color: var(--muted);
  font-size: 0.95rem;
}

main { overflow: hidden; }
.container { padding-inline: var(--gutter); }
.hero {
  min-height: calc(100vh - 5.4rem);
  display: grid;
  align-items: end;
  padding: clamp(5rem, 9vw, 8rem) var(--gutter) clamp(3rem, 6vw, 5rem);
}
.eyebrow {
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.display-title,
.page-title,
.contact-title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 800;
  letter-spacing: -0.075em;
  line-height: 0.9;
}
.display-title {
  max-width: 12ch;
  font-size: clamp(4.5rem, 14vw, 13.4rem);
}
.hero-meta {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(14rem, 26rem);
  gap: 2rem;
  align-items: end;
}
.hero-meta p {
  color: var(--muted);
  font-size: clamp(1rem, 1.5vw, 1.18rem);
}

.media-showcase {
  display: grid;
  grid-template-columns: 1.1fr 0.82fr 1.35fr;
  gap: clamp(0.7rem, 1.3vw, 1.15rem);
  padding: 0 var(--gutter) clamp(5.5rem, 10vw, 9rem);
}
.media-card {
  position: relative;
  min-height: clamp(22rem, 42vw, 39rem);
  overflow: hidden;
  border-radius: clamp(1.2rem, 2.2vw, 2rem);
}
.media-card:nth-child(1) { margin-top: 6vw; background: var(--terracotta); }
.media-card:nth-child(2) { min-height: clamp(15rem, 28vw, 27rem); background: var(--sage); }
.media-card:nth-child(3) { margin-top: 2vw; background: var(--sand); }
.media-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(135deg, rgba(255,255,255,0.22), transparent 42%),
    radial-gradient(circle at 75% 20%, rgba(26,26,26,0.16), transparent 18rem);
}
.media-label {
  position: absolute;
  left: 1.25rem;
  bottom: 1.1rem;
  color: rgba(26,26,26,0.72);
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.marquee-section {
  padding: clamp(3.5rem, 8vw, 7rem) 0;
  border-block: 1px solid var(--line);
  background: rgba(251, 247, 239, 0.34);
}
.marquee-heading {
  display: flex;
  justify-content: space-between;
  gap: 2rem;
  padding: 0 var(--gutter) 2rem;
  color: var(--muted);
}
.marquee-viewport {
  overflow: hidden;
  width: 100%;
  mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent);
}
.marquee-row {
  display: flex;
  width: max-content;
  animation: marquee-left 34s linear infinite;
  will-change: transform;
}
.marquee-row + .marquee-row { margin-top: 0.45rem; }
.marquee-row.reverse { animation-name: marquee-right; animation-duration: 38s; }
.marquee-track {
  display: flex;
  align-items: center;
  white-space: nowrap;
}
.marquee-track span {
  display: inline-flex;
  align-items: center;
  padding-inline: clamp(1rem, 2vw, 2.2rem);
  font-family: var(--serif);
  font-size: clamp(3.5rem, 8.8vw, 9rem);
  font-weight: 800;
  letter-spacing: -0.07em;
  line-height: 0.98;
}
.marquee-track span::after {
  content: '◦';
  margin-left: clamp(1.8rem, 3.2vw, 3.4rem);
  color: var(--terracotta);
  font-family: var(--sans);
  font-size: 0.42em;
  font-weight: 400;
}
@keyframes marquee-left { from { transform: translate3d(0,0,0); } to { transform: translate3d(-50%,0,0); } }
@keyframes marquee-right { from { transform: translate3d(-50%,0,0); } to { transform: translate3d(0,0,0); } }
@media (prefers-reduced-motion: reduce) { .marquee-row { animation-duration: 90s; } }

.about-section,
.editorial-section,
.services-intro,
.clients-intro,
.contact-links {
  padding: clamp(5.5rem, 11vw, 11rem) var(--gutter);
}
.split {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 1.35fr);
  gap: clamp(2rem, 8vw, 9rem);
}
.copy-stack {
  max-width: 62rem;
  display: grid;
  gap: 1.45rem;
  font-size: clamp(1.28rem, 2.45vw, 2.35rem);
  line-height: 1.2;
  letter-spacing: -0.035em;
}
.copy-stack strong { font-weight: 700; }

.page-hero {
  padding: clamp(5rem, 10vw, 9rem) var(--gutter) clamp(3rem, 7vw, 6rem);
}
.page-title {
  max-width: 10ch;
  font-size: clamp(4.3rem, 13.5vw, 12.5rem);
}
.page-kicker {
  max-width: 42rem;
  margin-top: 1.5rem;
  color: var(--muted);
  font-size: clamp(1.05rem, 1.8vw, 1.4rem);
}
.letter-wrap {
  max-width: 78rem;
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(8rem, 18rem) minmax(0, 46rem);
  gap: clamp(2rem, 7vw, 7rem);
  align-items: start;
}
.letter-card {
  position: sticky;
  top: 7rem;
  color: var(--muted);
  border-top: 1px solid var(--line);
  padding-top: 1rem;
}
.letter-body {
  font-family: var(--serif);
  font-size: clamp(1.55rem, 2.95vw, 2.75rem);
  line-height: 1.28;
  letter-spacing: -0.04em;
}
.letter-body p + p { margin-top: 2rem; }
.letter-body p:first-child::first-letter {
  float: left;
  padding: 0.12em 0.12em 0 0;
  color: var(--terracotta);
  font-size: 5.2em;
  line-height: 0.75;
}

.philosophy {
  max-width: 80rem;
  margin: 0 auto;
}
.philosophy h1 {
  margin: 0 0 1.4rem;
  font-family: var(--serif);
  font-size: clamp(4.2rem, 11vw, 11.5rem);
  line-height: 0.88;
  letter-spacing: -0.08em;
}
.philosophy-copy {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(1.5rem, 4vw, 4rem);
  margin-top: 3rem;
  font-size: clamp(1.2rem, 2vw, 1.8rem);
  line-height: 1.28;
  letter-spacing: -0.025em;
}
.big-divider {
  height: 1px;
  margin: 0 var(--gutter);
  background: var(--line);
}
.service-details {
  padding: clamp(5.5rem, 10vw, 10rem) var(--gutter);
}
.question {
  max-width: 18ch;
  margin: 0 0 clamp(3rem, 7vw, 6rem) auto;
  font-family: var(--serif);
  font-size: clamp(3rem, 7vw, 7.4rem);
  line-height: 0.94;
  letter-spacing: -0.07em;
}
.service-list {
  display: grid;
  gap: 1px;
  background: var(--line);
  border-block: 1px solid var(--line);
}
.service-item {
  display: grid;
  grid-template-columns: minmax(11rem, 0.55fr) minmax(0, 1.45fr);
  gap: clamp(1.5rem, 5vw, 5rem);
  padding: clamp(2rem, 5vw, 4.5rem) 0;
  background: var(--bg);
}
.service-item h2,
.client-card h2 {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(2.3rem, 4.8vw, 5rem);
  line-height: 0.95;
  letter-spacing: -0.065em;
}
.service-item p {
  max-width: 56rem;
  color: #332f2a;
  font-size: clamp(1.08rem, 1.45vw, 1.28rem);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--line);
  border-left: 1px solid var(--line);
  margin: 0 var(--gutter) clamp(5rem, 9vw, 9rem);
}
.client-card {
  min-height: 18rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 2rem;
  padding: clamp(1.25rem, 2.6vw, 2.4rem);
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: rgba(251,247,239,0.19);
  transition: background 220ms ease, transform 220ms ease;
}
.client-card:hover { background: rgba(216,189,145,0.16); }
.client-card p { color: var(--muted); max-width: 27rem; }

.contact-main {
  min-height: calc(100vh - 5.4rem);
  display: grid;
  align-content: center;
  padding: clamp(3rem, 8vw, 6rem) var(--gutter);
}
.contact-title {
  font-size: clamp(5.7rem, 25vw, 24rem);
  text-align: center;
  letter-spacing: -0.095em;
}
.contact-links {
  padding-top: clamp(1.5rem, 3vw, 2.5rem);
  text-align: center;
}
.contact-links ul {
  list-style: none;
  display: flex;
  justify-content: center;
  gap: clamp(1.2rem, 4vw, 4rem);
  padding: 0;
  margin: 0;
}
.contact-links a {
  color: var(--muted);
  font-size: clamp(1.4rem, 3vw, 3.2rem);
  font-family: var(--serif);
  letter-spacing: -0.055em;
  transition: color 180ms ease;
}
.contact-links a:hover { color: var(--ink); }

.reveal { animation: rise 850ms cubic-bezier(.2,.8,.2,1) both; }
.reveal.delay-1 { animation-delay: 110ms; }
.reveal.delay-2 { animation-delay: 220ms; }
@keyframes rise { from { opacity: 0; transform: translateY(22px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 860px) {
  .nav-links { display: none; }
  .menu-toggle { display: block; }
  .hero { min-height: 74vh; }
  .hero-meta,
  .split,
  .letter-wrap,
  .service-item { grid-template-columns: 1fr; }
  .media-showcase { grid-template-columns: 1fr; }
  .media-card,
  .media-card:nth-child(2) { min-height: 18rem; margin-top: 0; }
  .marquee-heading { display: block; }
  .copy-stack { font-size: clamp(1.35rem, 7vw, 2.2rem); }
  .letter-card { position: static; }
  .philosophy-copy { grid-template-columns: 1fr; }
  .clients-grid { grid-template-columns: 1fr; }
  .client-card { min-height: 14rem; }
  .contact-main { min-height: calc(100vh - 5rem); }
  .contact-links ul { flex-direction: column; gap: 0.8rem; }
}

@media (max-width: 520px) {
  :root { --gutter: 1rem; }
  .site-header { padding-block: 1rem; }
  .display-title { font-size: clamp(4rem, 21vw, 7rem); }
  .page-title { font-size: clamp(4rem, 20vw, 7rem); }
  .marquee-track span { font-size: clamp(3.1rem, 16vw, 5rem); }
  .letter-body { font-size: 1.5rem; }
  .philosophy h1 { font-size: clamp(3.8rem, 19vw, 6.5rem); }
}
